import sys, json
for line in sys.stdin:
    line = line.strip()
    if not line: continue
    try:
        d = json.loads(line)
        if d.get('type') == 'assistant':
            msg = d.get('message', {})
            for block in msg.get('content', []):
                if block.get('type') == 'text':
                    t = block['text']
                    if len(t) > 80:
                        print('---TEXT---')
